import{fs,db}from'/tmp/handoff-eleven.mjs';const campaign='gta-20261009-intro-v1';let jobs=[];for(let offset=0;;offset+=1000){const p=await db('sequence_jobs',{'sms_payload->>campaign_key':'eq.'+campaign,select:'id,batch_id,status,provider_sid,scheduled_at',order:'scheduled_at.asc,id.asc',offset:String(offset),limit:'1000'});jobs.push(...p);if(p.length<1000)break}if(jobs.length!==1000)throw Error('Unexpected campaign size');const ids=[...new Set(jobs.map(j=>j.batch_id))];const campaigns=await db('market_campaigns',{id:'in.('+ids.join(',')+')',select:'id,notes'});fs.writeFileSync('artifacts/realtor-batch-20261009/early-start-before.json',JSON.stringify({at:new Date().toISOString(),jobs,campaigns},null,2));const q=s=>"'"+String(s).replaceAll("'","''")+"'";const start=new Date(Date.now()+15000).toISOString();const sql=`begin;do $early$ begin
perform 1 from sequence_jobs where sms_payload->>'campaign_key'=${q(campaign)} for update;
if (select count(*) from sequence_jobs where sms_payload->>'campaign_key'=${q(campaign)})<>1000 then raise exception 'Queue changed'; end if;
with ranked as(select id,row_number() over(order by scheduled_at,id)-1 as n from sequence_jobs where sms_payload->>'campaign_key'=${q(campaign)} and status='pending' and provider_sid is null) update sequence_jobs j set scheduled_at=${q(start)}::timestamptz+ranked.n*interval '6 seconds' from ranked where j.id=ranked.id;
update market_campaigns set notes=(notes::jsonb || '{"endHour":18,"ownerEarlyFinishDate":"2026-10-09","requestedFinish":"17:30"}'::jsonb)::text where id::text in (${ids.map(q).join(',')});
end $early$;commit;`;const r=await fetch('https://api.supabase.com/v1/projects/idbyrtwdeeruiutoukct/database/query',{method:'POST',headers:{Authorization:'Bearer '+process.env.SUPABASE_ACCESS_TOKEN,'Content-Type':'application/json'},body:JSON.stringify({query:sql})});if(!r.ok)throw Error(await r.text());fs.writeFileSync('artifacts/realtor-batch-20261009/early-start-receipt.json',JSON.stringify({at:new Date().toISOString(),start,count:jobs.filter(j=>j.status==='pending'&&!j.provider_sid).length,spacing_seconds:6,owner_instruction:'Finish before 5:30pm if possible, by 6pm latest',end:new Date(Date.parse(start)+(jobs.filter(j=>j.status==='pending'&&!j.provider_sid).length-1)*6000).toISOString()},null,2));console.log('Rescheduled remaining pending jobs from '+start+' at 6-second spacing');
